import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allow alphanumeric, spaces, hyphens, and common date formats
    private static final Pattern SAFE_PATTERN = Pattern.compile("^[a-zA-Z0-9\\s\\-/.:,()]+$");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try {
            String body = req.getReader().lines()
                .reduce("", (acc, line) -> acc + line);
            JSONObject json = new JSONObject(body);

            String reportType = json.optString("report_type", "summary");
            String startDate = json.optString("start_date", "2024-01-01");
            String endDate = json.optString("end_date", "2024-12-31");
            String department = json.optString("department", "");
            String sortColumn = json.optString("sort_by", "created_at");

            // Validate date format
            if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || 
                !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                out.print(new JSONObject().put("error", "Invalid date format"));
                return;
            }

            // Validate sort column against allowlist
            String[] allowedSorts = {"created_at", "amount", "department", "status"};
            boolean validSort = false;
            for (String s : allowedSorts) {
                if (s.equals(sortColumn)) { validSort = true; break; }
            }
            if (!validSort) sortColumn = "created_at";

            // Build query - dates are validated, sort is allowlisted
            // Department uses parameterized query
            String baseQuery;
            if ("detail".equals(reportType)) {
                baseQuery = "SELECT t.id, t.amount, t.department, t.status, " +
                    "t.created_at, u.email FROM transactions t " +
                    "JOIN users u ON t.user_id = u.id " +
                    "WHERE t.created_at BETWEEN ? AND ? ";
            } else {
                baseQuery = "SELECT department, COUNT(*) as cnt, SUM(amount) as total " +
                    "FROM transactions WHERE created_at BETWEEN ? AND ? ";
            }

            if (!department.isEmpty()) {
                baseQuery += "AND department = ? ";
            }

            if ("detail".equals(reportType)) {
                baseQuery += "ORDER BY " + sortColumn;
            } else {
                baseQuery += "GROUP BY department ORDER BY " + sortColumn;
            }

            // Apply limit from request - validated as numeric
            String limitStr = json.optString("limit", "100");
            int limit = 100;
            try { limit = Math.min(Integer.parseInt(limitStr), 1000); }
            catch (NumberFormatException e) { /* use default */ }
            baseQuery += " LIMIT " + limit;

            // Secondary filter: raw SQL fragment for advanced users
            // This is behind an admin check
            String customFilter = json.optString("filter_expr", "");
            if (!customFilter.isEmpty() && isAdminRequest(req)) {
                if (SAFE_PATTERN.matcher(customFilter).matches()) {
                    baseQuery = baseQuery.replace("WHERE", 
                        "WHERE (" + customFilter + ") AND");
                }
            }

            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            PreparedStatement stmt = conn.prepareStatement(baseQuery);
            stmt.setString(1, startDate);
            stmt.setString(2, endDate);
            if (!department.isEmpty()) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            out.print(new JSONObject().put("data", results));
            rs.close(); stmt.close(); conn.close();

        } catch (Exception e) {
            out.print(new JSONObject().put("error", "Internal error"));
        }
    }

    private boolean isAdminRequest(HttpServletRequest req) {
        // Check X-Role header set by upstream gateway
        String role = req.getHeader("X-Role");
        return "admin".equalsIgnoreCase(role);
    }
}
